--
-- Name: cic_cms_has_permission(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cic_cms_has_permission(required_module text, required_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.cic_users u
    JOIN public.cic_user_roles ur ON ur.user_id = u.id AND ur.status = 'active'
    JOIN public.cic_roles r ON r.id = ur.role_id AND r.status = 'active'
    LEFT JOIN public.cic_role_permissions rp ON rp.role_id = r.id AND rp.allowed = true
    LEFT JOIN public.cic_permission_tasks pt ON pt.id = rp.permission_task_id AND pt.published = true
    WHERE u.auth_user_id = auth.uid()
      AND u.account_status = 'active' AND u.published IS DISTINCT FROM false
      AND (
        lower(r.code) IN ('admin', 'superadmin')
        OR (lower(pt.module) = lower(required_module) AND lower(rp.action) = lower(required_action))
      )
  );
$$;


--
-- Name: cic_cms_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cic_cms_user_id() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT id FROM public.cic_users
  WHERE auth_user_id = auth.uid()
    AND account_status = 'active' AND published IS DISTINCT FROM false
  LIMIT 1;
$$;


--
-- Name: cic_enforce_news_placement_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cic_enforce_news_placement_limit() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  enabled_count integer;
BEGIN
  IF NEW.is_hot IS TRUE THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(TG_TABLE_NAME||':is_hot', 0));
    EXECUTE format('SELECT count(*) FROM public.%I WHERE is_hot IS TRUE AND id <> $1', TG_TABLE_NAME)
      INTO enabled_count USING coalesce(NEW.id, -1);
    IF enabled_count >= 4 THEN
      RAISE EXCEPTION '% supports at most 4 Hot News articles', TG_TABLE_NAME USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.show_in_homepage IS TRUE THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(TG_TABLE_NAME||':show_in_homepage', 0));
    EXECUTE format('SELECT count(*) FROM public.%I WHERE show_in_homepage IS TRUE AND id <> $1', TG_TABLE_NAME)
      INTO enabled_count USING coalesce(NEW.id, -1);
    IF enabled_count >= 4 THEN
      RAISE EXCEPTION '% supports at most 4 Home News articles', TG_TABLE_NAME USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END $_$;


--
-- Name: cic_reject_audit_log_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cic_reject_audit_log_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('app.audit_retention_mode', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'cic_activity_logs is append-only';
  END IF;
  RETURN OLD;
END;
$$;


