--
-- Name: cic_activity_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cic_activity_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id integer,
    actor_label character varying(255),
    action_code character varying(100) NOT NULL,
    category character varying(50) NOT NULL,
    severity character varying(16) NOT NULL,
    is_sensitive boolean DEFAULT false NOT NULL,
    entity_type character varying(100) NOT NULL,
    entity_id character varying(100),
    entity_title text,
    module character varying(100),
    workspace character varying(50) NOT NULL,
    locale character varying(10),
    result character varying(16) NOT NULL,
    result_message text,
    session_id character varying(100),
    correlation_id character varying(100),
    source_app character varying(100),
    environment character varying(20),
    ip_address inet,
    user_agent text,
    http_method character varying(10),
    endpoint text,
    execution_time_ms integer,
    before_data jsonb,
    after_data jsonb,
    redacted_fields text[],
    CONSTRAINT cic_activity_logs_execution_time_ms_check CHECK ((execution_time_ms >= 0)),
    CONSTRAINT cic_activity_logs_result_check CHECK (((result)::text = ANY ((ARRAY['success'::character varying, 'failed'::character varying, 'partial'::character varying, 'denied'::character varying])::text[]))),
    CONSTRAINT cic_activity_logs_severity_check CHECK (((severity)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[])))
);


